<?php require __DIR__.'/includes/bootstrap.php';header('Content-Type: application/json; charset=utf-8');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false]);exit;}verify_csrf();$slug=preg_replace('/[^a-z0-9-]/','',strtolower($_POST['slug']??''));$status=$_POST['status']??'';if(!in_array($status,['attending','maybe','declined'],true)){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Please select an RSVP option.']);exit;}$guests=max(1,min(20,(int)($_POST['guests']??1)));$message=trim(substr((string)($_POST['message']??''),0,1000));$stmt=$pdo->prepare('UPDATE guests SET rsvp_status=?,rsvp_guests=?,rsvp_message=? WHERE slug=? AND is_active=1');$stmt->execute([$status,$guests,$message,$slug]);if(!$stmt->rowCount()){http_response_code(404);echo json_encode(['ok'=>false,'message'=>'Invitation not found.']);exit;}echo json_encode(['ok'=>true,'message'=>$status==='attending'?'Thank you! We look forward to celebrating with you!':'Thank you. Your response has been saved.']);

